function formatMetricsSection(metrics: {
  productivityMetrics: {
    totalIssuesCount: number;
    averageResolutionDays: number;
    responseSpeedScore: number;
    reopenedIssuesCount: number;
    reopenRatePercentage: number;
  };
  issuesByPriority: {
    critical: number;
    high: number;
    medium: number;
    low: number;
  };
  issuesByCategory: Record<string, number>;
}): string {
  const pm = metrics.productivityMetrics;
  const priority = metrics.issuesByPriority;

  let section = `### 生産性メトリクス
- 総課題件数: ${pm.totalIssuesCount}件
- 平均解決期間: ${pm.averageResolutionDays}日
- 対応速度スコア: ${pm.responseSpeedScore}/100
- 再発課題件数: ${pm.reopenedIssuesCount}件
- 再発率: ${pm.reopenRatePercentage}%

### 優先度別課題分布
- 緊急(Critical): ${priority.critical}件
- 高(High): ${priority.high}件
- 中(Medium): ${priority.medium}件
- 低(Low): ${priority.low}件

### カテゴリ別課題分布
`;

  Object.entries(metrics.issuesByCategory).forEach(([category, count]) => {
    section += `- ${category}: ${count}件\n`;
  });

  return section;
}

function formatTrendsSection(trends: {
  issueCountTrend: "increasing" | "stable" | "decreasing";
  resolutionSpeedTrend: "improving" | "stable" | "degrading";
  criticalIssueFrequency: "high" | "medium" | "low";
}): string {
  const trendLabels: Record<string, string> = {
    increasing: "増加傾向",
    stable: "安定",
    decreasing: "減少傾向",
    improving: "改善傾向",
    degrading: "悪化傾向",
    high: "高い",
    medium: "中程度",
    low: "低い",
  };

  return `- 課題件数トレンド: ${trendLabels[trends.issueCountTrend]}
- 解決速度トレンド: ${trendLabels[trends.resolutionSpeedTrend]}
- 緊急課題の発生頻度: ${trendLabels[trends.criticalIssueFrequency]}`;
}

function formatRecurrenceSection(
  patterns: Array<{
    issueTitle: string;
    occurrenceCount: number;
    lastOccurrenceDate: string;
    categoryTag: string;
  }>
): string {
  if (patterns.length === 0) {
    return "再発パターンは検出されていません。";
  }

  let section = "### 検出された再発パターン\n";
  patterns.forEach((pattern, index) => {
    section += `${index + 1}. **${pattern.issueTitle}**
   - 発生回数: ${pattern.occurrenceCount}回
   - 最終発生日: ${pattern.lastOccurrenceDate}
   - カテゴリ: ${pattern.categoryTag}\n`;
  });

  return section;
}

function formatPerformanceSection(
  members: Array<{
    memberId: string;
    memberName: string;
    issuesReported: number;
    averageResolutionDays: number;
    reportQualityScore: number;
  }>
): string {
  if (members.length === 0) {
    return "チーム別パフォーマンスデータはありません。";
  }

  let section = "### メンバー別パフォーマンス\n";
  members.forEach((member) => {
    section += `- **${member.memberName}** (ID: ${member.memberId})
  - 報告課題数: ${member.issuesReported}件
  - 平均解決日数: ${member.averageResolutionDays}日
  - 報告品質スコア: ${member.reportQualityScore}/100\n`;
  });

  return section;
}

function formatPreviousMeasuresSection(
  measures: Array<{
    measureTitle: string;
    implementationDate: string;
    effectivenessScore: number;
    status: "active" | "completed" | "discontinued";
  }>
): string {
  if (measures.length === 0) {
    return "過去の改善施策データはありません。";
  }

  let section = "### 過去の改善施策実績\n";
  measures.forEach((measure) => {
    const statusLabel: Record<string, string> = {
      active: "実施中",
      completed: "完了",
      discontinued: "中止",
    };

    section += `- **${measure.measureTitle}**
  - 実装日: ${measure.implementationDate}
  - 効果スコア: ${measure.effectivenessScore}/100
  - ステータス: ${statusLabel[measure.status]}\n`;
  });

  return section;
}
